// Run after /tmp/code-graph-live-fixture.js generated by prepare-live-fixture.py.
async (page) => {
 const checks=[];const assert=(ok,message)=>{if(!ok)throw new Error(message);checks.push(message);};
 const work=page.getByTestId('code-graph-workspace'),source=page.getByTestId('code-graph-source'),relations=page.getByTestId('code-graph-relations');
 const mode=page.getByRole('combobox',{name:'关系视图',exact:true});
 const search=async(query,label)=>{await page.getByLabel('搜索符号',{exact:true}).fill(query);await page.getByRole('button',{name:'搜索',exact:true}).click();await page.getByRole('button',{name:label,exact:true}).click();};
 const graphDone=()=>page.waitForFunction(()=>{const control=document.querySelector('select[aria-label="查询跳数"]')||document.querySelector('select[aria-label="聚合层级"]');return control&&!control.disabled;});
 const requests=()=>page.evaluate(()=>fetch('/__codegraph-test').then(r=>r.json()).then(s=>s.requests));
 try{
  await page.evaluate(()=>{localStorage.setItem('tdai-memory.lang','zh-CN');localStorage.removeItem('codegraph-test-no-webgl');});await page.reload();await page.setViewportSize({width:1600,height:1100});
  await page.getByRole('button',{name:'Live SDK CodeGraph',exact:true}).click();await page.getByRole('tab',{name:'关系图',exact:true}).click();
  await search('entry','entry function src/main.ts:2');await source.locator('pre').filter({hasText:'export function entry()'}).waitFor();
  await page.getByRole('button',{name:'关系列表',exact:true}).click();await graphDone();
  assert((await relations.innerText()).includes('leaf')&&(await relations.innerText()).includes('top'),'real SDK call graph shows caller and callee with indexed source');
  await mode.selectOption('impact');await graphDone();
  assert((await page.getByTestId('code-graph-impact-list').innerText()).includes('top'),'real reverse impact traversal reaches top');
  await page.getByTestId('code-graph-impact-list').getByRole('button',{name:'查看 top 的证据路径',exact:true}).click();
  assert((await page.getByTestId('code-graph-path').innerText()).includes('top → entry'),'real impact evidence remains top → entry');
  await mode.selectOption('hierarchy');await search('Child','Child class src/main.ts:4');await graphDone();
  assert((await relations.innerText()).includes('extends')&&(await relations.innerText()).includes('implements')&&(await relations.innerText()).includes('Base'),'real class graph contains extends and implements');
  await mode.selectOption('dependencies');await graphDone();
  assert((await page.getByTestId('code-graph-cycles').innerText()).includes('alpha')&&(await page.getByTestId('code-graph-cycles').innerText()).includes('beta'),'real imports confirm alpha/beta circular dependency group');
  assert((await work.innerText()).includes('星号重导出'),'real SDK import coverage warning reaches UI');
  await page.getByRole('combobox',{name:'聚合层级',exact:true}).selectOption('file');await graphDone();
  const lateEdge=relations.locator('table').nth(1).locator('tbody tr').filter({hasText:'late.ts'}).first();await lateEdge.getByRole('button').last().click();
  const evidence=page.getByTestId('code-graph-dependency-evidence');await evidence.getByRole('button').first().waitFor();
  assert((await evidence.innerText()).includes('late.ts:1000'),'real dependency anchor resolves declaration at line 1000');
  await evidence.getByRole('button').first().click();await source.locator('pre').filter({hasText:'import { leaf } from "./base"'}).waitFor();
  const sourceRequest=(await requests()).filter(r=>r.path.endsWith('/graph-source')).at(-1).body;
  assert(sourceRequest.sourceLine===1000&&(await source.getByRole('link').getAttribute('href')).includes('#L1000-L1000'),'real source request locates line 1000 and immutable link uses the same line');
  const sourceLines=await source.locator('pre ._codegraph-line').allTextContents();
  assert(sourceLines.includes('1000')&&sourceLines.length<=300,'real source snippet contains requested evidence while respecting 300-line budget');
  await mode.selectOption('clusters');await graphDone();
  const nodes=relations.locator('table').first();await nodes.getByRole('button',{name:'src',exact:true}).click();await page.getByRole('button',{name:'下钻到文件',exact:true}).click();await graphDone();
  assert((await relations.innerText()).includes('跨组端点'),'real cluster file scope retains external boundary groups');
  await nodes.getByRole('button',{name:'src/main.ts',exact:true}).click();await page.getByRole('button',{name:'查看文件内符号',exact:true}).click();await graphDone();
  await nodes.getByRole('button',{name:'entry',exact:true}).click();await source.locator('pre').filter({hasText:'export function entry()'}).waitFor();
  assert(true,'real cluster drilldown reaches SDK symbol and same-snapshot source');
  await page.getByRole('navigation',{name:'聚类浏览路径'}).getByRole('button',{name:'仓库根目录',exact:true}).click();await graphDone();
  assert(await page.getByRole('combobox',{name:'聚合层级',exact:true}).inputValue()==='directory','real cluster breadcrumbs return to directory overview');
  await mode.selectOption('calls');await search('jsEntry','jsEntry function javascript.js:2');await graphDone();
  assert((await relations.innerText()).includes('jsLeaf'),'real JavaScript call extraction is visible in the same workspace');
  const sent=await requests(),graphRequests=sent.filter(r=>r.path.endsWith('/graph'));
  assert(new Set(graphRequests.map(r=>r.body.mode)).size===5,'all five graph modes were served by the real Panel→Knowledge→SDK chain');
  const versions=new Set(sent.filter(r=>/\/graph(?:-source|-node)?$/.test(r.path)).map(r=>r.body.indexVersion).filter(Boolean));
  assert(versions.size===1,'graph/node/source requests keep one real index version across all five modes');
  await page.screenshot({path:'/Users/zj/daydayup/TencentDB-Agent-Memory/output/playwright/codegraph-live-chain.png',fullPage:true});
  return{checks,browser:await page.context().browser().version(),indexVersions:[...versions],requestCounts:{graph:graphRequests.length,source:sent.filter(r=>r.path.endsWith('/graph-source')).length},scope:'Real SDK 1.6.2 index → Knowledge HTTP → Panel HTTP → production browser UI. Identity, repository catalog and metadata/ACL are local fixtures; no production service/account changed.'};
 }catch(error){await page.screenshot({path:'/Users/zj/daydayup/TencentDB-Agent-Memory/output/playwright/codegraph-live-failure.png',fullPage:true});throw new Error(JSON.stringify({checks,error:String(error)}));}
}
